import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.DnrXFDHb.js";const b=JSON.parse('{"title":"电力市场 · 价格面板","description":"","frontmatter":{"tags":["电力市场","价格"],"updated":"2026-06-24T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"电力新能源/电力市场/赛道文件.md","filePath":"电力新能源/电力市场/赛道文件.md","lastUpdated":1782315727000}'),o={name:"电力新能源/电力市场/赛道文件.md"};function l(i,t,h,n,s,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="电力市场-·-价格面板" tabindex="-1">电力市场 · 价格面板 <a class="header-anchor" href="#电力市场-·-价格面板" aria-label="Permalink to &quot;电力市场 · 价格面板&quot;">​</a></h1><blockquote><p>手动更新于 2026/6/24（数据来源：北极星电力市场网 2026.6.15-6.21 周报）</p></blockquote><h2 id="💰-各省现货市场均价" tabindex="-1">💰 各省现货市场均价 <a class="header-anchor" href="#💰-各省现货市场均价" aria-label="Permalink to &quot;💰 各省现货市场均价&quot;">​</a></h2><table tabindex="0"><thead><tr><th>省份</th><th>日前最低(元/MWh)</th><th>日前最高(元/MWh)</th><th>实时最低(元/MWh)</th><th>实时最高(元/MWh)</th><th>均价中枢</th></tr></thead><tbody><tr><td>广东</td><td>135.71</td><td>477.76</td><td>128.45</td><td>536.98</td><td>~460</td></tr><tr><td>山西</td><td>205.28</td><td>318.19</td><td>191.46</td><td>334.56</td><td>~260</td></tr><tr><td>山东</td><td>303.55</td><td>460.36</td><td>235.69</td><td>436.53</td><td>~350</td></tr><tr><td>蒙西</td><td>188.24</td><td>276.38</td><td>188.24</td><td>276.38</td><td>~240</td></tr><tr><td>陕西</td><td>66.38</td><td>313.63</td><td>82.08</td><td>303.97</td><td>~150</td></tr><tr><td>辽宁</td><td>112.60</td><td>324.79</td><td>106.77</td><td>357.37</td><td>~200</td></tr><tr><td>江苏</td><td>325.22</td><td>369.63</td><td>333.73</td><td>380.05</td><td>~350</td></tr><tr><td>安徽</td><td>177.07</td><td>298.55</td><td>155.62</td><td>315.12</td><td>~250</td></tr></tbody></table><h2 id="📊-电改进度概览-截至2026年6月" tabindex="-1">📊 电改进度概览（截至2026年6月） <a class="header-anchor" href="#📊-电改进度概览-截至2026年6月" aria-label="Permalink to &quot;📊 电改进度概览（截至2026年6月）&quot;">​</a></h2><h3 id="已正式运行-7省" tabindex="-1">已正式运行（7省） <a class="header-anchor" href="#已正式运行-7省" aria-label="Permalink to &quot;已正式运行（7省）&quot;">​</a></h3><p>山西(2023)、广东(2024.6)、山东(2024.6)、甘肃(2024.9)、蒙西(2025.2)、湖北(2025.6)、浙江(2025底)</p><h3 id="即将转正-5省" tabindex="-1">即将转正（5省） <a class="header-anchor" href="#即将转正-5省" aria-label="Permalink to &quot;即将转正（5省）&quot;">​</a></h3><p>安徽(2026.6)、陕西(2026.6)、辽宁(2026)、河北南网(2026)、南方区域市场(2026Q4)</p><h3 id="长周期试运行" tabindex="-1">长周期试运行 <a class="header-anchor" href="#长周期试运行" aria-label="Permalink to &quot;长周期试运行&quot;">​</a></h3><p>福建、四川、江苏、湖南、河南、宁夏、重庆、上海、吉林</p><h3 id="短周期-未启动" tabindex="-1">短周期/未启动 <a class="header-anchor" href="#短周期-未启动" aria-label="Permalink to &quot;短周期/未启动&quot;">​</a></h3><p>江西、黑龙江、新疆、蒙东、青海</p><h2 id="🔑-2026年关键变化" tabindex="-1">🔑 2026年关键变化 <a class="header-anchor" href="#🔑-2026年关键变化" aria-label="Permalink to &quot;🔑 2026年关键变化&quot;">​</a></h2><ol><li><strong>负电价正式化</strong>：辽宁引入-100元/MWh下限</li><li><strong>容量电价分化</strong>：广东气电涨164%-296%，煤电涨65%</li><li><strong>新能源全面入市</strong>：136号文要求30-50%电量入市</li><li><strong>售电盈利模式重构</strong>：广东取消浮动费用，批零价差消失</li></ol><h2 id="📌-投资含义" tabindex="-1">📌 投资含义 <a class="header-anchor" href="#📌-投资含义" aria-label="Permalink to &quot;📌 投资含义&quot;">​</a></h2><ul><li><strong>电价梯度 = 选址梯度</strong>：蒙西/甘肃/陕西低价区→算电协同首选</li><li><strong>地理套利空间</strong>：蒙西(~240) vs 广东(~460)，价差近1倍</li><li><strong>时点套利</strong>：陕西日前最低66元 vs 最高313元，日内价差4.7倍</li></ul><blockquote><p>详细分析见：<code>01-研究笔记/电改2.0进度地图_各省电力市场化进度研究.md</code></p></blockquote>',18)])])}const p=d(o,[["render",l]]);export{b as __pageData,p as default};
